// Snapshot the MDX articles the chat assistant searches into a JSON module.
//
// The chat API used to read content/ from disk on every request. Cloudflare
// Workers have no project filesystem at runtime, so the text is captured here
// at build time (npm "prebuild"/"predev") and bundled into the worker instead.
// Chunking and indexing still happen in src/lib/chat-knowledge.ts.
//
// Output: src/generated/chat-corpus.ts (gitignored, regenerated by npm
// prebuild/predev/pretest). A .ts module rather than JSON so Next, tsc and the
// node:test resolve hooks all import it the same way.
import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";

const ROOT = process.cwd();
const CONTENT_DIR = path.join(ROOT, "content");
const OUT_FILE = path.join(ROOT, "src", "generated", "chat-corpus.ts");

// Keep in step with MDX_SOURCES in src/lib/chat-knowledge.ts.
const SOURCES = [
  { subdir: "blog", base: "/blog" },
  { subdir: "knowledge-center/product-info", base: "/knowledge-center/product-info" },
  { subdir: "knowledge-center/tutorials", base: "/knowledge-center/tutorials" },
];

const docs = [];
for (const { subdir, base } of SOURCES) {
  const dir = path.join(CONTENT_DIR, subdir);
  if (!fs.existsSync(dir)) throw new Error(`build-chat-corpus: missing ${path.relative(ROOT, dir)}`);
  const files = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".mdx") || f.endsWith(".md"))
    .sort();
  for (const file of files) {
    const { data, content } = matter(fs.readFileSync(path.join(dir, file), "utf8"));
    const slug = file.replace(/\.mdx?$/, "");
    docs.push({ title: String(data.title ?? slug), url: `${base}/${slug}`, content });
  }
}

if (docs.length === 0) throw new Error("build-chat-corpus: no articles found under content/");

fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(
  OUT_FILE,
  [
    "// Generated by scripts/build-chat-corpus.mjs from content/. Do not edit.",
    "export interface CorpusDoc { title: string; url: string; content: string }",
    `export const docs: CorpusDoc[] = ${JSON.stringify(docs)};`,
    "",
  ].join("\n"),
);
console.log(`build-chat-corpus: ${docs.length} articles -> ${path.relative(ROOT, OUT_FILE)}`);
